template <typename Predicate> constexpr unary_negate<Predicate> not1(const Predicate& pred); 
template <typename Predicate> class binary_negate; 
// where unary_negate and binary_negate are template classes that implement predicate negation logic

code_example:
#include <type_traits>

template <typename Predicate>
class unary_negate {
public:
    explicit constexpr unary_negate(Predicate pred) : pred_(pred) {}
    constexpr bool operator()(auto&&... args) const {
        return !pred_(std::forward<decltype(args)>(args)...);
    }
private:
    Predicate pred_;
};

template <typename Predicate>
constexpr unary_negate<Predicate> not1(const Predicate& pred) {
    return unary_negate<Predicate>(pred);
}

template <typename Predicate>
class binary_negate {
public:
    explicit constexpr binary_negate(Predicate pred) : pred_(pred) {}
    constexpr bool operator()(auto&&... args) const {
        return !pred_(std::forward<decltype(args)>(args)...);
    }
private:
    Predicate pred_;
};

int main() {
    auto is_even = [](int n) { return n % 2 == 0; };
    auto is_odd = not1(is_even); // Negates the predicate at compile time
    static_assert(!is_even(3), "3 is not even");
    static_assert(is_odd(3), "3 is odd after negation");
    return 0;
}
